let cycle=false;const seen=new Set(),open=new Set();
function visit(id){if(open.has(id)){cycle=true;return;} if(seen.has(id))return;open.add(id);for(const i of producers.get(id)?.inputs||[])visit(i);open.delete(id);seen.add(id);}
